    description: { de: "Ein mittelalterliches Kloster, das teilweise in den angrenzenden Berg gehauen wurde und zum UNESCO-Welterbe gehört.", hu: "Középkori kolostor, amelyet részben a szomszédos hegybe vájtak, és az UNESCO világörökség része.", ro: "O mănăstire medievală săpată parțial în muntele adiacent, parte a Patrimoniului Mondial UNESCO.", en: "A medieval monastery being partially carved out of the adjacent mountain, surrounded by cliffs." , es: "Un monasterio medieval parcialmente excavado en la montaña adyacente que es Patrimonio de la Humanidad por la UNESCO.", pt: "Um mosteiro medieval parcialmente esculpido na montanha adjacente e classificado como Patrimônio Mundial da UNESCO.", fr: "Un monastère médiéval partiellement creusé dans la montagne adjacente, inscrit au patrimoine mondial de l'UNESCO."},
    facts: {
      de: ["Gegründet im 4. Jahrhundert von Gregor dem Erleuchter.", "Benannt nach der Lanze, die Jesus am Kreuz verletzte."],
      hu: ["Világosító Szent Gergely alapította a 4. században.", "Arról a lándzsáról kapta a nevét, amely megsebezte Jézust."],
      ro: ["Fondată în secolul al IV-lea de Grigore Iluminătorul.", "Numită după sulița care l-a rănit pe Iisus la cruce."],
      en: ["Founded in the 4th century by Gregory the Illuminator.", "Named after the spear that wounded Jesus at the Crucifixion."],
      es: ["Fundado en el siglo IV por Gregorio el Iluminador.", "Llamado así por la lanza que hirió a Jesús en la cruz."],
      pt: ["Fundado no século IV por Gregório, o Iluminador.", "Batizado em homenagem à lança que feriu Jesus na cruz."],
      fr: ["Fondé au IVe siècle par Grégoire l'Illuminateur.", "Nommé d'après la lance qui a blessé Jésus sur la croix."],
    }, image: "/poi-images/geghard-monastery-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Kloster Geghard ist eine einzigartige mittelalterliche Anlage in der armenischen Provinz Kotajk, die teilweise direkt in den angrenzenden Felsen gehauen wurde. Ursprünglich im 4. Jahrhundert vom Heiligen Gregor dem Erleuchter an der Stelle einer heiligen Quelle gegründet, stammen die heutigen Hauptgebäude aus dem 13. Jahrhundert. Der Name 'Geghard' bedeutet 'Lanze' und bezieht sich auf die Lanze, mit der Jesus am Kreuz verwundet wurde und die jahrhundertelang hier aufbewahrt wurde. Die Architektur ist meisterhaft, mit Kirchen und Grabkammern, die direkt aus dem Stein gemeißelt sind und eine außergewöhnliche Akustik sowie mystische Lichtverhältnisse bieten. Das Kloster steht auf der Liste des UNESCO-Weltkulturerbes und ist von steilen Klippen der Asat-Schlucht umgeben. Zahlreiche Chatschkare (Kreuzsteine) schmücken die Felswände und Zeugen von der tiefen religiösen Bedeutung des Ortes. Geghard ist bis heute ein bedeutendes Ziel für Pilger und Touristen, die die spirituelle Atmosphäre und die architektonische Harmonie schätzen.",
      hu: "A Geghard-kolostor egy egyedülálló középkori épületegyüttes az örmény Kotajk tartományban, amelynek egy részét közvetlenül a szomszédos sziklába vájták. Eredetileg a 4. században alapította Világosító Szent Gergely egy szent forrás helyén, a mai főépületek többsége azonban a 13. századból származik. A 'Geghard' név jelentése 'lándzsa', ami arra a fegyverre utal, amellyel Jézust a kereszten megsebezték, és amelyet évszázadokon át itt őriztek. Az építészet mesteri, a sziklából kifaragott templomok és sírkamrák különleges akusztikát és misztikus fényviszonyokat teremtenek. A kolostor az UNESCO Világörökség része, és az Azat-folyó szurdokának meredek sziklái ölelik körbe. Számos hacskar (örmény keresztkő) díszíti a sziklafalakat, tanúskodva a hely mély vallási jelentőségéről. Geghard ma is fontos zarándokhely és turisztikai célpont, ahol a látogatók megtapasztalhatják a spirituális légkört és az építészeti harmóniát.",
      ro: "Mănăstirea Geghard este un complex medieval unic situat în provincia armeană Kotayk, fiind parțial săpat direct în stânca muntelui adiacent. Fondată inițial în secolul al IV-lea de Sfântul Grigore Luminătorul pe locul unui izvor sfânt, clădirile principale actuale datează din secolul al XIII-lea. Numele 'Geghard' înseamnă 'suliță' și se referă la sulița cu care a fost rănit Iisus pe cruce, relicvă care a fost păstrată aici timp de secole. Arhitectura este magistrală, cu biserici și camere funerare dăltuite direct în piatră, oferind o acustică excepțională și condiții de iluminare mistică. Mănăstirea este inclusă pe lista Patrimoniului Mondial UNESCO și este înconjurată de stâncile abrupte ale defileului râului Azat. Numeroase katchkar-uri (cruci de piatră) împodobesc pereții stâncoși, demonstrând semnificația religioasă profundă a locului. Geghard rămâne până astăzi o destinație importantă pentru pelerini și turiști, care apreciază atmosfera spirituală și armonia arhitecturală.",
      en: "Geghard Monastery is a unique medieval complex in Armenia's Kotayk province, partially carved directly into the adjacent mountain cliffs. Originally founded in the 4th century by Saint Gregory the Illuminator at the site of a sacred spring, the current main structures date back to the 13th century. The name 'Geghard' means 'spear' in Armenian, referring to the Holy Lance that wounded Christ on the cross, which was kept here for centuries. The architecture is masterful, featuring churches and tombs chiseled out of solid rock, creating exceptional acoustics and mystical lighting effects. The monastery is a UNESCO World Heritage site and is surrounded by the towering cliffs of the Azat River gorge. Numerous khachkars (cross-stones) adorn the rock faces, bearing witness to the site's profound religious significance. Geghard remains a major pilgrimage destination and tourist site, celebrated for its spiritual atmosphere and architectural harmony.",
      es: "El monasterio de Geghard es conocido por sus estilos arquitectónicos grabados en las rocas de Garni.",
      pt: "O mosteiro de Geghard é conhecido pelos seus estilos arquitetônicos esculpidos nas rochas de Garni.",
      fr: "Le monastère de Geghard est réputé pour ses styles architecturaux sculptés à même les rochers de Garni.",
    },
    factsAdvanced: {
      de: ["Gegründet im 4. Jahrhundert", "Hauptkirche erbaut im Jahr 1215", "Gehört zum UNESCO-Weltkulturerbe", "Teilweise in massiven Fels gehauen", "Hütete einst die Heilige Lanze", "Liegt in der malerischen Asat-Schlucht"],
      hu: ["A 4. században alapították", "A főtemplom 1215-ben épült", "Az UNESCO Világörökség része", "Részben a sziklába vájták", "Egykor a Szent Lándzsát őrizte", "Az Azat-folyó szurdokában található"],
      ro: ["Fondată în secolul al IV-lea", "Biserica principală construită în 1215", "Inclusă în Patrimoniul Mondial UNESCO", "Săpată parțial în stâncă masivă", "A adăpostit cândva Sulița Sfântă", "Situată în defileul râului Azat"],
      en: ["Founded in the 4th century", "Main church built in 1215", "A UNESCO World Heritage site", "Partially carved into solid rock", "Once housed the Holy Lance", "Located in the Azat River gorge"],
      es: ["El monasterio principal fue erigido en 1215.", "Es un sitio del Patrimonio Mundial de la UNESCO.", "La capilla contiene reliquias de Jesús y Juan el Bautista.", "Hay un total de 4 iglesias en el complejo."],
      pt: ["O mosteiro foi erguido em 1215.", "É um sítio do Patrimônio Mundial da UNESCO.", "A capela contém relíquias de Jesus e de João Batista.", "Existem ao todo 4 igrejas no complexo."],
      fr: ["Le monastère a été érigé en 1215.", "C'est un site classé au patrimoine mondial de l'UNESCO.", "La chapelle contient des reliques de Jésus et de Jean le Baptiste.", "Le complexe comprend au total 4 églises."],
    },
