    coords: [46.2497, 39.3802],
    name: { de: "Kloster Tatew", hu: "Tatev-kolostor", ro: "Mănăstirea Tatev", en: "Tatev Monastery"},
    image: "/poi-images/tatev-monastery-history-v2.webp",
    description: { de: "Ein befestigtes Kloster auf einem großen Basaltplateau, das im Mittelalter ein wichtiges intellektuelles Zentrum war.", hu: "Erődített kolostor egy nagy bazaltfennsíkon, amely a középkorban fontos szellemi központ volt.", ro: "O mănăstire fortificată situată pe un mare platou de bazalt, care a fost un important centru intelectual în Evul Mediu.", en: "A 9th-century historical monument standing on the edge of a deep gorge of the Vorotan River." , es: "Un monasterio fortificado sobre una gran meseta de basalto, que fue un importante centro intelectual en la Edad Media.", pt: "Um mosteiro fortificado num grande planalto de basalto, que foi um importante centro intelectual na Idade Média.", fr: "Un monastère fortifié sur un grand plateau basaltique, qui fut un centre intellectuel majeur au Moyen Âge."},
    facts: {
      de: ["Gegründet im 9. Jahrhundert.", "Die Pendelbahn Wings of Tatev führt zum Kloster."],
      hu: ["A 9. században alapították.", "A Tatev szárnyai nevű kötélpálya vezet a kolostorhoz."],
      ro: ["Fondată în secolul al IX-lea.", "Telecabina Wings of Tatev duce spre mănăstire."],
      en: ["Founded in the 9th century.", "Reached by the Wings of Tatev aerial tramway."],
      es: ["Fundado en el siglo IX.", "El teleférico Wings of Tatev conduce al monasterio."],
      pt: ["Fundado no século IX.", "O teleférico Wings of Tatev conduz ao mosteiro."],
      fr: ["Fondé au IXe siècle.", "Le téléphérique Wings of Tatev mène au monastère."],
    }, image: "/poi-images/tatev-monastery-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Kloster Tatev ist ein Juwel der mittelalterlichen armenischen Architektur und thront auf einem gewaltigen Basaltplateau im Süden des Landes. Gegründet im 9. Jahrhundert, entwickelte es sich schnell zum geistigen und politischen Zentrum des Fürstentums Sjunik. Die Hauptkirche, Surb Poghos-Petros (Heilige Paul und Peter), wurde zwischen 895 und 906 errichtet und ist für ihre imposante Kuppel und die Gavazan-Säule bekannt – eine freistehende Säule, die Erschütterungen anzeigt. Im 14. und 15. Jahrhundert beherbergte das Kloster die Universität von Tatev, eine der wichtigsten Bildungseinrichtungen des Mittelalters in der Region. Die Anlage ist von wehrhaften Mauern umgeben und liegt an der Kante der tiefen Worotan-Schlucht. Seit 2010 ist das Kloster durch die 'Wings of Tatev' erreichbar, eine der längsten reversiblen Seilbahnen der Welt, die einen atemberaubenden Blick bietet. Tatev ist ein Symbol für das Überleben und die kulturelle Blüte Armeniens über die Jahrhunderte hinweg.",
      hu: "A tatevi kolostor a középkori örmény építészet egyik gyöngyszeme, amely egy hatalmas bazaltplatón trónol az ország déli részén. A 9. században alapították, és gyorsan a Szjunik fejedelemség szellemi és politikai központjává vált. A főtemplom, a Surb Poghos-Petros (Szent Pál és Péter), 895 és 906 között épült, és híres impozáns kupolájáról, valamint a Gavazan-oszlopról – egy különálló oszlopról, amely a földmozgásokat jelzi. A 14. és 15. században a kolostor adott otthont a Tatevi Egyetemnek, amely a régió egyik legfontosabb középkori oktatási intézménye volt. Az épületegyüttest erős falak veszik körül a mély Vorotan-szurdok peremén. 2010 óta a kolostor elérhető a 'Tatev szárnyai' nevű libegővel, amely a világ egyik leghosszabb kötélpályája, és lélegzetelállító kilátást nyújt. Tatev az örmény kultúra fennmaradásának és virágzásának szimbóluma az évszázadok során.",
      ro: "Mănăstirea Tatev este o bijuterie a arhitecturii medievale armene, cocoțată pe un platou uriaș de bazalt în sudul țării. Fondată în secolul al IX-lea, s-a dezvoltat rapid ca centru spiritual și politic al principatului Syunik. Biserica principală, Surb Poghos-Petros (Sfinții Petru și Pavel), a fost construită între 895 și 906, fiind renumită pentru cupola sa impunătoare și coloana Gavazan – o coloană autoportantă care indică vibrațiile solului. În secolele XIV și XV, mănăstirea a găzduit Universitatea din Tatev, una dintre cele mai importante instituții de învățământ medievale din regiune. Complexul este înconjurat de ziduri de apărare puternice, situate la marginea adâncului defileu Vorotan. Din 2010, mănăstirea este accesibilă prin 'Wings of Tatev', una dintre cele mai lungi telecabine reversibile din lume, oferind o priveliște uluitoare. Tatev este un simbol al supraviețuirii și înfloririi culturale a Armeniei de-a lungul secolelor.",
      en: "Tatev Monastery is a jewel of medieval Armenian architecture, perched on a vast basalt plateau in the southern part of the country. Founded in the 9th century, it rapidly evolved into the spiritual and political center of the Syunik Principality. The main church, Surb Poghos-Petros (Saints Peter and Paul), was constructed between 895 and 906 and is famous for its imposing dome and the Gavazan pillar—a freestanding column designed to detect seismic movements. During the 14th and 15th centuries, the monastery housed the University of Tatev, one of the region's most important medieval educational institutions. The complex is enclosed by formidable defensive walls at the edge of the deep Vorotan River gorge. Since 2010, the monastery has been accessible via the 'Wings of Tatev,' one of the world's longest reversible cable cars, which offers breathtaking views. Tatev remains a symbol of Armenia's resilience and cultural flourishing throughout the centuries.",
      es: "El monasterio de Tatev es un lugar religioso significativo en Armenia, conocido por sus edificios medievales y su importancia histórica.",
      pt: "O mosteiro de Tatev é um local religioso significativo na Arménia, conhecido pelos seus edifícios medievais e importância histórica.",
      fr: "Le monastère de Tatev est un site religieux majeur en Arménie, réputé pour ses édifices médiévaux et son importance historique.",
    },
    factsAdvanced: {
      de: ["Kloster im 9. Jahrhundert gegründet", "Hauptkirche zwischen 895 und 906 erbaut", "Sitz der Universität von Tatev", "Lage an der tiefen Worotan-Schlucht", "Besitzt die schwingende Gavazan-Säule", "Erreichbar mit den 'Wings of Tatev'"],
      hu: ["A kolostort a 9. században alapították", "A főtemplom 895-906 között épült", "A Tatevi Egyetem egykori székhelye", "A Vorotan-szurdok peremén található", "Itt található a lengő Gavazan-oszlop", "A 'Tatev szárnyai' libegővel elérhető"],
      ro: ["Mănăstire fondată în secolul al IX-lea", "Biserica principală construită între 895-906", "Sediul Universității medievale din Tatev", "Situată pe marginea defileului Vorotan", "Deține coloana oscilantă Gavazan", "Accesibilă prin telecabina 'Wings of Tatev'"],
      en: ["Monastery founded in the 9th century", "Main church built between 895-906", "Former seat of the University of Tatev", "Located on the edge of the Vorotan gorge", "Home to the swaying Gavazan pillar", "Accessible via the 'Wings of Tatev' cable car"],
      es: ["El complejo fue fundado en el año 895.", "Es un sitio del Patrimonio Mundial de la UNESCO.", "El complejo comprende varias iglesias y claustros.", "Tatev fue un centro de la cultura y ciencia armenias."],
      pt: ["O complexo foi fundado no ano 895.", "É um local classificado pela UNESCO.", "O complexo inclui várias igrejas e mosteiros.", "Tatev foi um centro da cultura e ciência arménias."],
      fr: ["Le site a été fondé en 895.", "Il est classé au patrimoine mondial de l'UNESCO.", "Le complexe comprend plusieurs églises et monastères.", "Tatev était un centre de la culture et de la science arméniennes."],
    },
