    type: "monument",
    parent: "AM-ER",
    coords: [44.5247, 40.1953],
    name: { de: "Mutter Armenien", hu: "Örményország Anyja", ro: "Mama Armenia", en: "Mother Armenia"},
    image: "/poi-images/mother-armenia-history-v2.webp",
    description: { de: "Eine monumentale Statue in Jerewan, die den Frieden durch Stärke symbolisiert.", hu: "Egy monumentális szobor Jerevánban, amely az erőn keresztüli békét szimbolizálja.", ro: "O statuie monumentală în Erevan care simbolizează pacea prin putere.", en: "A female personification of Armenia, located in Victory Park, Yerevan." , es: "Una estatua monumental en Ereván que simboliza la paz a través de la fuerza.", pt: "Uma estátua monumental em Erevan que simboliza a paz através da força.", fr: "Une statue monumentale à Erevan, symbolisant la paix par la force."},
    facts: {
      de: ["Ersetzte 1967 eine monumentale Statue von Josef Stalin.", "Das Podest beherbergt ein Militärmuseum."],
      hu: ["1967-ben Sztálin monumentális szobrát váltotta fel.", "A talapzatban egy hadtörténeti múzeum kapott helyet."],
      ro: ["A înlocuit o statuie monumentală a lui Stalin în 1967.", "Piedestalul adăpostește un muzeu militar."],
      en: ["Replaced a monumental statue of Joseph Stalin in 1967.", "The pedestal houses the Military Museum."],
      es: ["Sustituyó en 1967 a una estatua monumental de Iósif Stalin.", "El pedestal alberga un museo militar."],
      pt: ["Substituiu em 1967 uma estátua monumental de Josef Stalin.", "O pedestal abriga um museu militar."],
      fr: ["A remplacé en 1967 une statue monumentale de Joseph Staline.", "Le piédestal abrite un musée militaire."],
    }, image: "/poi-images/mother-armenia-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Monument Mutter Armenien im Siegespark von Eriwan wurde 1967 errichtet und ersetzte eine Stalin-Statue, die seit 1950 auf demselben Sockel stand. Die 22 Meter hohe Kupferstatue wurde vom Bildhauer Ara Harutjunjan entworfen und thront auf einem 31 Meter hohen Basaltsockel, was eine Gesamthöhe von 51 Metern ergibt. Das Denkmal symbolisiert Frieden durch Stärke und stellt eine weibliche Wächterfigur dar, die ein Schwert in der Scheide hält. Im massiven Sockel befindet sich das Militärmuseum des Verteidigungsministeriums, das Exponate zum Zweiten Weltkrieg und zum Bergkarabach-Konflikt zeigt. Die Statue ist so ausgerichtet, dass sie symbolisch das gesamte Land überblickt und schützt. Von der Plattform des Denkmals bietet sich ein beeindruckender Panoramablick auf die armenische Hauptstadt und den Berg Ararat.",
      hu: "Az Örményország Anyja emlékmű Jereván Győzelem parkjában található, és 1967-ben állították fel a korábbi Sztálin-szobor helyére. Ara Harutjunjan szobrászművész alkotása egy 22 méter magas rézszobor, amely egy 31 méteres bazalt talapzaton áll, így az összmagassága eléri az 51 métert. A monumentális alak egy hüvelybe helyezett kardot tartó nőt ábrázol, aki a nemzet erejét és védelmezőjét jelképezi. A talapzat belsejében a Védelmi Minisztérium katonai múzeuma működik, amely a második világháború és a hegyi-karabahi konfliktus emlékeit őrzi. A szobor szimbolikusan az örmény határ felé néz, őrizve a nép békéjét és biztonságát. Az emlékmű lábától páratlan panoráma nyílik az örmény fővárosra és a háttérben magasodó Ararát-hegyre.",
      ro: "Monumentul Mama Armenia din Parcul Victoriei din Erevan a fost ridicat în anul 1967, înlocuind o statuie a lui Stalin care ocupase același piedestal din 1950. Statuia de cupru, înaltă de 22 de metri, a fost creată de sculptorul Ara Harutyunyan și se află pe un soclu de bazalt de 31 de metri, atingând o înălțime totală de 51 de metri. Monumentul simbolizează pacea prin forță, reprezentând o figură feminină care ține o sabie în teacă, fiind protectoarea simbolică a națiunii. În interiorul piedestalului masiv se află un muzeu militar dedicat Ministerului Apărării, care găzduiește exponate din Al Doilea Război Mondial și conflictul din Nagorno-Karabah. Statuia este poziționată astfel încât să domine vizual întreaga capitală, oferind protecție spirituală locuitorilor. De pe platforma monumentului, vizitatorii pot admira o vedere panoramică asupra orașului Erevan și a Muntelui Ararat.",
      en: "The Mother Armenia monument in Victory Park, Yerevan, was erected in 1967, replacing a massive statue of Joseph Stalin that had stood on the same pedestal since 1950. Designed by sculptor Ara Harutyunyan, the 22-meter-tall hammered copper statue rests on a 31-meter basalt pedestal, reaching a total height of 51 meters. The monument personifies the female guardian of the nation, holding a sheathed sword, which symbolizes peace through strength. Inside the massive pedestal, there is a military museum operated by the Ministry of Defense, featuring exhibits related to World War II and the Nagorno-Karabakh conflict. The statue is strategically positioned overlooking the city, serving as a prominent landmark and a symbol of national identity. From its observation deck, visitors can enjoy panoramic views of the Armenian capital and the majestic Mount Ararat in the distance.",
      es: "La Madre Armenia es una estatua imponente en Ereván que sirve como símbolo del heroísmo de los armenios.",
      pt: "A Mãe Armênia é uma estátua imponente em Erevan que serve como símbolo do heroísmo dos armênios.",
      fr: "La Mère Arménie est une statue imposante à Erevan, servant de symbole à l'héroïsme des Arméniens.",
    },
    factsAdvanced: {
      de: ["Baujahr des aktuellen Denkmals: 1967", "Gesamthöhe inklusive Sockel: 51 Meter", "Material der Statue: gehämmertes Kupfer", "Entworfen vom Bildhauer Ara Harutjunjan", "Der Sockel beherbergt ein Militärmuseum", "Ersetzte eine Stalin-Statue von 1950"],
      hu: ["Az emlékművet 1967-ben avatták fel", "A szobor és talapzat együttes magassága 51 méter", "A szobor anyaga kalapált réz", "Ara Harutjunjan szobrász tervezte az alakot", "A talapzatban katonai múzeum található", "Egy 1950-ben állított Sztálin-szobrot váltott fel"],
      ro: ["Monumentul a fost inaugurat în anul 1967", "Înălțimea totală cu piedestal este de 51 metri", "Statuia este realizată din cupru bătut", "Sculptorul monumentului a fost Ara Harutyunyan", "Piedestalul adăpostește un muzeu militar", "A înlocuit o statuie a lui Stalin din 1950"],
      en: ["Inaugurated in 1967 as a replacement for Stalin", "Total height with the pedestal is 51 meters", "The statue itself is 22 meters tall", "Designed by the sculptor Ara Harutyunyan", "Houses a museum dedicated to the Ministry of Defense", "The pedestal was originally built in 1950"],
      es: ["La estatua se completó en 1950.", "Se alza sobre un pedestal elevado en el norte de Ereván.", "La figura tiene 22 metros de altura.", "Se trata de un símbolo de la seguridad nacional."],
      pt: ["A estátua foi concluída em 1950.", "Fica sobre um pedestal alto no norte de Erevan.", "A figura tem 22 metros de altura.", "Trata-se de um símbolo da segurança nacional."],
      fr: ["La statue a été achevée en 1950.", "Elle se dresse sur un socle élevé au nord d'Erevan.", "La statue mesure 22 mètres de haut.", "C'est un symbole de la sécurité nationale."],
    },
