    name: { de: "Kirche von Oschakan", hu: "Osakan-templom", ro: "Biserica Oshakan", en: "Oshakan Church"},
    image: "/poi-images/oshakan-church-history-v2.webp",
    description: { de: "Eine Kirche, die über dem Grab von Mesrop Maschtoz, dem Erfinder des armenischen Alphabets, errichtet wurde.", hu: "Templom, amelyet Meszrop Mastoc, az örmény ábécé megalkotójának sírja fölé emeltek.", ro: "O biserică construită deasupra mormântului lui Mesrop Maștoț, inventatorul alfabetului armean.", en: "A church built over the grave of Mesrop Mashtots, the creator of the Armenian alphabet." , es: "Una iglesia construida sobre la tumba de Mesrop Mashtots, el inventor del alfabeto armenio.", pt: "Uma igreja construída sobre o túmulo de Mesrop Mashtots, o inventor do alfabeto armênio.", fr: "Une église érigée sur le tombeau de Mesrop Machtots, l'inventeur de l'alphabet arménien."},
    facts: {
      de: ["Der Erfinder des armenischen Alphabets ist hier begraben.", "Das armenische Alphabet wurde im Jahr 405 geschaffen."],
      hu: ["Itt nyugszik az örmény ábécé megalkotója.", "Az örmény ábécét 405-ben hozták létre."],
      ro: ["Inventatorul alfabetului armean este înmormântat aici.", "Alfabetul armean a fost creat în anul 405."],
      en: ["The creator of the Armenian alphabet is buried here.", "The Armenian alphabet was created in the year 405."],
      es: ["El inventor del alfabeto armenio está enterrado aquí.", "El alfabeto armenio fue creado en el año 405."],
      pt: ["O inventor do alfabeto armênio está enterrado aqui.", "O alfabeto armênio foi criado no ano 405."],
      fr: ["L'inventeur de l'alphabet arménien est enterré ici.", "L'alphabet arménien a été créé en l'an 405."],
    }, image: "/poi-images/oshakan-church-history-v2.webp",
    descriptionAdvanced: {
      de: "Die Kirche von Oschakan ist eine der bedeutendsten Pilgerstätten Armeniens, da sie die Grabstätte von Mesrop Maschtoz beherbergt, dem Erfinder des armenischen Alphabets. Die ursprüngliche Kapelle über seinem Grab wurde bereits im 5. Jahrhundert kurz nach seinem Tod im Jahr 440 errichtet. Das heutige Gebäude der Sankt-Mesrop-Maschtoz-Kirche stammt aus den Jahren 1875 bis 1879 und wurde auf Initiative von Katholikos Georg IV. erbaut. Die Kirche ist als dreischiffige Basilika konzipiert und besitzt einen eleganten Glockenturm an der Ostseite. Im Inneren führt eine Treppe hinab zur Krypta, in der sich der Schrein des Heiligen unter dem Altar befindet. Das Grabmal ist mit kunstvollen Reliefs verziert und zieht jährlich Tausende von Schülern und Lehrern an. In der Nähe der Kirche befindet sich ein Park mit steinernen Skulpturen aller 36 (heute 39) Buchstaben des armenischen Alphabets. Oschakan bleibt damit ein lebendiges Symbol der armenischen kulturellen Identität und Schriftkunst.",
      hu: "Az osakani templom Örményország egyik legfontosabb zarándokhelye, mivel itt található Meszrop Mastoc, az örmény ábécé megalkotója sírhelye. Az eredeti kápolnát közvetlenül a tudós szerzetes 440-ben bekövetkezett halála után emelték a sírja fölé a 5. században. A mai Szent Meszrop Mastoc-templom 1875 és 1879 között épült IV. György katolikosz kezdeményezésére, a korábbi épületek alapjain. A bazilikális elrendezésű építmény keleti oldalán egy elegáns harangtorony magasodik. A templom belsejében lépcső vezet le a kriptába, ahol a szent ereklyéit őrző márvány síremlék található az oltár alatt. A síremléket finom faragások díszítik, és minden évben diákok ezrei látogatnak el ide, hogy tisztelegjenek az írásbeliség megteremtője előtt. A templom szomszédságában egy parkot alakítottak ki, ahol az örmény ábécé betűit formázó kőszobrok láthatók. Osakan így az örmény nemzeti öntudat és kultúra egyik örök szimbóluma marad.",
      ro: "Biserica din Oșacan este unul dintre cele mai importante locuri de pelerinaj din Armenia, adăpostind mormântul lui Mesrop Maștoț, creatorul alfabetului armean. O capelă inițială a fost ridicată deasupra mormântului său în secolul al V-lea, la scurt timp după moartea sa în anul 440. Actuala structură a bisericii Sfântul Mesrop Maștoț a fost construită între anii 1875 și 1879, sub egida Catolicosului Gevorg al IV-lea. Biserica este o bazilică cu trei nave, având o clopotniță distinctivă adăugată pe partea estică. În interior, sub altarul principal, se află cripta care păstrează moaștele sfântului într-un sarcofag de marmură decorat cu basoreliefuri. Situl atrage anual mii de elevi și profesori care vin să aducă un omagiu părintele literaturii armene. În apropierea lăcașului de cult se află un parc tematic cu sculpturi din piatră reprezentând toate literele alfabetului armean. Oșacan simbolizează astfel legătura indestructibilă dintre credință, limbă și identitate națională.",
      en: "The Oshakan Church is a premier pilgrimage site in Armenia, serving as the final resting place of Saint Mesrop Mashtots, the inventor of the Armenian alphabet. After his death in 440 AD, a small chapel was initially built over his grave by Vahan Amatuni. The current Saint Mesrop Mashtots Cathedral was constructed between 1875 and 1879 by Catholicos George IV on the foundations of the earlier structures. The church is a hall-style basilica featuring a unique cylindrical bell tower with an octagonal roof on the eastern side. Inside the cathedral, a staircase leads down to the underground crypt where the saint's tomb is located directly beneath the main altar. The tomb is elaborately decorated and remains a focal point for Armenian pilgrims, especially students beginning their education. Adjacent to the church, a stone alphabet park features large sculptures of the 36 original Armenian letters. Oshakan stands as an enduring monument to the intellectual and spiritual resilience of the Armenian people.",
      es: "La iglesia de Oshakan se encuentra cerca de la localidad de Mets Mashtots y es un lugar cristiano de gran importancia.",
      pt: "A igreja de Oshakan situa-se perto da localidade de Mets Mashtots e é um local cristão de grande importância.",
      fr: "L'église d'Ochakan est située près du lieu-dit Mets Machtots et constitue un site chrétien majeur.",
    },
    factsAdvanced: {
      de: ["Grabstätte von Mesrop Maschtoz (alphabet)", "Aktuelle Kirche erbaut 1875–1879", "Besitzt eine Krypta unter dem Altar", "Gelegen in der Provinz Aragazotn", "Zentrum für Bildung und Schriftkunst", "Naher Park zeigt Steinalphabetskulpturen"],
      hu: ["Meszrop Mastoc, az ábécéalkotó sírhelye", "A jelenlegi templom 1875–1879-ben épült", "Kriptája közvetlenül az oltár alatt van", "Aragatsotn tartományban található", "Az örmény írásbeliség központja", "Kőbe faragott ábécé-szobrok vannak mellette"],
      ro: ["Mormântul lui Mesrop Maștoț (inventatorul alfabetului)", "Biserica actuală datează din 1875–1879", "Cripta este situată sub altarul principal", "Localizată în satul Oșacan, Aragatsotn", "Loc principal de pelerinaj pentru studenți", "Găzduiește sculpturi ale literelor armenești"],
      en: ["Burial site of Saint Mesrop Mashtots", "Current structure built between 1875–1879", "The saint died in 440 AD and was buried here", "Located in the Aragatsotn Province", "Features a hall-type basilica architecture", "Surrounded by a unique alphabet stone park"],
      es: ["La iglesia fue construida en el siglo XVII.", "Es un lugar de peregrinación para los armenios.", "Oshakan es una importante reliquia cristiana.", "El nombre recuerda al creador del alfabeto armenio."],
      pt: ["A igreja foi construída no século XVII.", "É um local de peregrinação para os armênios.", "Oshakan é uma importante relíquia cristã.", "O nome homenageia o criador do alfabeto armênio."],
      fr: ["L'église a été construite au XVIIe siècle.", "C'est un lieu de pèlerinage pour les Arméniens.", "Ochakan est une relique chrétienne importante.", "Le nom rappelle le créateur de l'alphabet arménien."],
    },
