    name: { de: "Festung Daschtadem", hu: "Dastadem-erőd", ro: "Cetatea Dashtadem", en: "Dashtadem Fortress"},
    image: "/poi-images/dashtadem-fortress-history-v2.webp",
    description: { de: "Eine weitläufige mittelalterliche Festung, die vom 10. bis zum 19. Jahrhundert kontinuierlich erweitert wurde.", hu: "Kiterjedt középkori erőd, amelyet a 10. századtól a 19. századig folyamatosan bővítettek.", ro: "O vastă cetate medievală, extinsă continuu din secolul al X-lea până în secolul al XIX-lea.", en: "A substantial medieval fortress, continuously expanded from the 10th to the 19th centuries." , es: "Una extensa fortaleza medieval que fue ampliada continuamente desde el siglo X hasta el XIX.", pt: "Uma vasta fortaleza medieval que foi continuamente ampliada do século X ao XIX.", fr: "Une vaste forteresse médiévale qui a été continuellement agrandie du Xe au XIXe siècle."},
    facts: {
      de: ["Besteht aus zwei massiven Verteidigungsmauern.", "Diente dem Schutz der westlichen Grenzen Armeniens."],
      hu: ["Két masszív védőfalból áll.", "Örményország nyugati határainak védelmére szolgált."],
      ro: ["Este formată din două ziduri masive de apărare.", "A servit la protejarea granițelor vestice ale Armeniei."],
      en: ["Features two massive defensive walls.", "Served to protect the western borders of Armenia."],
      es: ["Consta de dos muros defensivos masivos.", "Servía para proteger las fronteras occidentales de Armenia."],
      pt: ["É composta por duas muralhas defensivas massivas.", "Servia para proteger as fronteiras ocidentais da Arménia."],
      fr: ["Se compose de deux massifs murs de défense.", "Servait à protéger les frontières occidentales de l'Arménie."],
    }, image: "/poi-images/dashtadem-fortress-history-v2.webp",
    descriptionAdvanced: {
      de: "Die Festung Daschtadem ist eine beeindruckende Verteidigungsanlage in der Provinz Aragazotn, deren Ursprünge bis in die Zeit des Kamsarakan-Adelsgeschlechts im 7. Jahrhundert zurückreichen. Der Komplex besteht aus einer inneren Zitadelle mit einem achteckigen Hauptturm, der im 10. Jahrhundert durch die Bagratiden-Könige verstärkt wurde. Im 12. Jahrhundert erweiterten die Sakarjaden die Anlage, bevor sie später unter persische und osmanische Herrschaft fiel. Daschtadem zeichnet sich durch zwei konzentrische Verteidigungsmauern aus, wobei die äußere Mauer zahlreiche halbrunde Türme und Schießscharten besitzt. Innerhalb des Festungsareals befindet sich die Surb-Sargis-Kapelle aus dem 10. Jahrhundert sowie Reste von Wohngebäuden und Wasserreservoirs. Die Festung war strategisch so positioniert, dass sie die Ebene von Schirak überblickte und wichtige Handelswege schützte. Umfangreiche Restaurierungsarbeiten in den letzten Jahren haben die Struktur der massiven Basaltmauern gesichert und die Anlage für Besucher zugänglich gemacht.",
      hu: "Dastadem vára az örményországi Aragatsotn tartomány egyik legjelentősebb erődítménye, amelynek alapjai a 7. századig, a Kamszarakan család idejéig nyúlnak vissza. A komplexum központi eleme egy belső citadella egy nyolcszögletű toronnyal, amelyet a 10. században a Bagratuni királyok erősítettek meg. A 12. században a Zakarian-hercegek tovább bővítették a várat, amely később perzsa és oszmán kézre is került. Dastadem építészetileg két koncentrikus falgyűrűjével tűnik ki, a külső falat számos félköríves bástya és lőrés teszi látványossá. A vár területén belül található a 10. századi Surb Sargis kápolna, valamint lakóépületek és víztározók maradványai. Az erőd stratégiai elhelyezkedése lehetővé tette a Shirak-fennsík és a fontos kereskedelmi útvonalak ellenőrzését. Az elmúlt években végzett jelentős restaurálási munkálatoknak köszönhetően a bazaltból épült falak nagy része megújult, így a vár ma az ország egyik leglátogatottabb történelmi emléke.",
      ro: "Cetatea Dashtadem este o structură defensivă impresionantă din provincia Aragatsotn, ale cărei origini urcă până în secolul al VII-lea, fiind fondată de familia nobiliară Kamsarakan. Complexul cuprinde o citadelă interioară cu un turn central octogonal, fortificat ulterior în secolul al X-lea de către regii Bagratizi. În secolul al XII-lea, prinții Zakarian au extins ansamblul, care a servit mai târziu drept fortăreață pentru diverse puteri regionale, inclusiv persani și otomani. Dashtadem este remarcabilă pentru sistemul său de ziduri concentrice, cel exterior fiind dotat cu numeroase bastioane semicirculare și metereze. În incinta fortăreței se află capela Surb Sargis din secolul al X-lea, alături de vestigii ale unor clădiri rezidențiale și rezervoare de apă. Poziția sa strategică domina câmpia Shirak, asigurând protecția rutelor comerciale vitale. Recent, situl a beneficiat de ample lucrări de restaurare care au consolidat zidurile masive de bazalt, redându-i cetății grandoarea de odinioară.",
      en: "Dashtadem Fortress is a significant defensive complex in the Aragatsotn Province, with its oldest layers dating back to the Kamsarakan noble family in the 7th century. The heart of the site is an inner citadel featuring an octagonal keep, which was reinforced during the 10th century by the Bagratid kings. In the 12th century, the Zakarian princes further expanded the fortifications, which later saw use during the Persian and Ottoman periods. Architecturally, Dashtadem is distinct for its two concentric defensive circuits; the outer wall is punctuated by numerous semi-circular towers and battlements. Within the enclosure, visitors can find the 10th-century Surb Sargis chapel, along with ruins of medieval dwellings and water cisterns. The fortress was strategically placed to command the Shirak plain and protect regional trade routes from invaders. Recent extensive restoration efforts have stabilized the massive basalt structures, making it one of the most accessible and impressive military monuments in modern Armenia.",
      es: "La fortaleza de Dashtadem es una impresionante instalación defensiva medieval en Armenia, que existe desde el siglo I a. C.",
      pt: "A fortaleza de Dashtadem é uma impressionante instalação defensiva medieval na Arménia, que existe desde o século I a.C.",
      fr: "La forteresse de Dashtadem est un impressionnant ouvrage défensif médiéval en Arménie, qui existe depuis le Ier siècle av. J.-C.",
    },
    factsAdvanced: {
      de: ["Gegründet im 7. Jahrhundert", "Besitzt eine achteckige Zitadelle", "Wurde im 12. Jhd. von Sakarjaden erweitert", "Zwei konzentrische Verteidigungsmauern", "Enthält die Surb-Sargis-Kapelle (10. Jhd.)", "Gelegen in der Provinz Aragazotn"],
      hu: ["A 7. században alapították", "Nyolcszögletű központi tornya van", "A 12. században a Zakarianok bővítették", "Két koncentrikus védőfala van", "A Surb Sargis kápolna a 10. századból való", "Aragatsotn tartományban fekszik"],
      ro: ["Originile datează din secolul al VII-lea", "Dispune de un turn central octogonal", "Extinsă considerabil în secolul al XII-lea", "Protejată de două rânduri de ziduri", "Include capela Surb Sargis din secolul X", "Situată în provincia Aragatsotn"],
      en: ["First built in the 7th century AD", "Features a prominent octagonal citadel", "Major 12th-century additions by Zakarians", "Has double concentric defensive walls", "Home to the 10th-century Surb Sargis church", "Located near the village of Dashtadem"],
      es: ["La fortaleza fue construida en el siglo IV.", "El nombre significa 'Lugar de la paz'.", "Tiene una superficie de 37 hectáreas.", "Dashtadem es administrada por el Ministerio de Asuntos del Ejército."],
      pt: ["A fortaleza foi construída no século IV.", "O nome significa 'Lugar da paz'.", "Tem uma área de 37 hectares.", "Dashtadem é administrada pelo Ministério dos Assuntos do Exército."],
      fr: ["La forteresse a été construite au IVe siècle.", "Le nom signifie 'Lieu de paix'.", "Elle s'étend sur une surface de 37 hectares.", "Dashtadem est gérée par le ministère des Affaires militaires."],
    },
