    description: { de: "Die Überreste einer der größten Kirchen Armeniens aus dem 7. Jahrhundert, mit einer einstmals riesigen Kuppel.", hu: "Örményország egyik legnagyobb 7. századi templomának maradványai, amelynek egykor hatalmas kupolája volt.", ro: "Rămășițele uneia dintre cele mai mari biserici din Armenia, din secolul al VII-lea, cu un fost dom imens.", en: "The remains of one of the largest 7th-century Armenian churches, originally featuring a massive dome." , es: "Los restos de una de las iglesias más grandes de Armenia del siglo VII, con una cúpula que antaño fue enorme.", pt: "Os restos de uma das maiores igrejas da Arménia do século VII, com uma cúpula que outrora foi enorme.", fr: "Les vestiges de l'une des plus grandes églises d'Arménie datant du VIIe siècle, dotée autrefois d'une coupole immense."},
    facts: {
      de: ["Die gewaltige Kuppel stürzte bei einem Erdbeben ein.", "War Teil eines großen Palastkomplexes."],
      hu: ["A hatalmas kupola egy földrengés során beomlott.", "Egy nagy palotakomplexum része volt."],
      ro: ["Domul enorm s-a prăbușit într-un cutremur.", "Făcea parte dintr-un mare complex palatinal."],
      en: ["The massive dome collapsed during an earthquake.", "Was originally part of a large palace complex."],
      es: ["La enorme cúpula se derrumbó durante un terremoto.", "Formaba parte de un gran complejo palaciego."],
      pt: ["A enorme cúpula desabou durante um terramoto.", "Faziam parte de um grande complexo palaciano."],
      fr: ["L'immense coupole s'est effondrée lors d'un tremblement de terre.", "Faisait partie d'un vaste complexe de palais."],
    }, image: "/poi-images/aruchavank-history-v2.webp",
    descriptionAdvanced: {
      de: "Die Kathedrale von Arutsch, auch bekannt als Arutschawank, ist eine der größten und architektonisch bedeutendsten Kirchen Armeniens aus dem 7. Jahrhundert. Sie wurde in den 660er Jahren unter der Schirmherrschaft von Fürst Grigor Mamikonjan errichtet und stellt den Typus der kuppelgekrönten Hallenkirche dar. Trotz des Verlusts der ursprünglichen Kuppel beeindruckt der monumentale Innenraum durch seine weiten Dimensionen und die Überreste bedeutender Fresken. In der Apsis sind noch Spuren einer monumentalen Darstellung Christi zu sehen, die zu den frühesten Beispielen armenischer Wandmalerei gehört. Direkt neben der Kirche befinden sich die Ruinen eines herrschaftlichen Palastes, der ebenfalls aus dem 7. Jahrhundert stammt und die Bedeutung von Arutsch als politische Residenz unterstreicht. Die Anlage spiegelt den Übergangsstil der frühchristlichen armenischen Architektur wider, der durch technische Präzision und schlichte Eleganz gekennzeichnet ist. Arutschawank ist ein wichtiges Ziel für Forscher, die sich mit der Entwicklung der Kuppelkonstruktionen im Kaukasus beschäftigen.",
      hu: "Az aruicsi székesegyház, más néven Arutschavank, Örményország egyik legnagyobb és építészetileg legjelentősebb 7. századi temploma. Az építkezést az 660-as években Grigor Mamikonjan herceg finanszírozta, aki a kor egyik legbefolyásosabb örmény vezetője volt. A templom egy kupolás csarnoktípusú építmény, amely monumentális méreteivel emelkedik ki a korabeli szakrális épületek közül. Bár az eredeti kupola az évszázadok során beomlott, a belső tér tágassága és a falakon látható 7. századi freskótöredékek ma is lenyűgözőek. Az apszisban Krisztus ábrázolásának nyomai láthatók, ami az egyik legkorábbi falfestmény az országban. A templom közvetlen szomszédságában egy fejedelmi palota romjai találhatók, amely szintén a 7. századból származik, bizonyítva, hogy Aruics fontos politikai és közigazgatási központ volt. Az épületegyüttes a korai örmény keresztény építészet technikai fejlettségének és letisztult eleganciájának kiemelkedő példája.",
      ro: "Catedrala din Aruici, cunoscută și sub numele de Aruchavank, este una dintre cele mai mari și mai importante biserici din secolul al VII-lea din Armenia. A fost construită în anii 660 d.Hr. sub patronajul prințului Grigor Mamikonian, fiind o biserică de tip hală cu cupolă. Deși cupola originală s-a prăbușit de-a lungul timpului, interiorul monumental impresionează prin dimensiunile sale vaste și prin fragmentele de fresce datând din perioada construcției. În absidă se pot observa încă urmele unei reprezentări grandioase a lui Hristos, unul dintre cele mai vechi exemple de pictură murală armeană. Adiacent bisericii se află ruinele unui palat princiar, tot din secolul al VII-lea, care confirmă rolul localității Aruici ca reședință politică și culturală majoră în acea epocă. Arhitectura sitului reflectă rafinamentul tehnic al constructorilor armeni timpurii, caracterizat prin zidărie precisă și un stil auster, dar impunător. Aruchavank rămâne un reper esențial pentru studiul evoluției arhitecturii ecleziastice în Caucaz.",
      en: "Aruchavank, also known as the Cathedral of Aruch, is one of the largest and most architecturally significant Armenian churches from the 7th century. It was commissioned in the 660s by Prince Grigor Mamikonian and represents the domed-hall type of religious architecture. Although the central dome collapsed centuries ago, the monumental interior remains awe-inspiring due to its sheer scale and the remnants of its original 7th-century frescoes. The apse contains traces of a massive depiction of Christ, which is among the earliest documented examples of Armenian wall painting. Adjacent to the cathedral lie the extensive ruins of a secular palace, also dating from the 7th century, emphasizing Aruch's importance as a princely residence and administrative center. The ensemble showcases the transition from early Christian to classical medieval Armenian styles, noted for its precise stone masonry and elegant proportions. Aruchavank is a vital site for scholars investigating the development of structural engineering and decorative arts in the early medieval Near East.",
      es: "Aruchavank es un complejo monástico medieval en Armenia, famoso por sus iglesias inusuales.",
      pt: "Aruchavank é um complexo monástico medieval na Arménia, famoso pelas suas igrejas invulgares.",
      fr: "Aruchavank est un complexe monastique médiéval en Arménie, célèbre pour ses églises inhabituelles.",
    },
    factsAdvanced: {
      de: ["Erbaut in den 660er Jahren n. Chr.", "Größte kuppelgekrönte Halle Armeniens", "Stifter war Fürst Grigor Mamikonjan", "Beherbergt Freskenreste aus dem 7. Jhd.", "Nebenruinen eines Palastes vorhanden", "Liegt in der Provinz Aragazotn"],
      hu: ["Az 660-as években épült", "Örményország egyik legnagyobb csarnoktemploma", "Grigor Mamikonjan herceg építtette", "7. századi freskótöredékeket őriz", "Egy fejedelmi palota romjai állnak mellette", "Aragatsotn tartományban található"],
      ro: ["Construită în anii 660 d.Hr.", "Cea mai mare biserică de tip hală din Armenia", "Fondată de prințul Grigor Mamikonian", "Păstrează fresce rare din secolul al VII-lea", "Include ruinele unui palat princiar adiacent", "Situată în provincia Aragatsotn"],
      en: ["Built in the 660s AD", "One of the largest medieval halls in Armenia", "Founded by Prince Grigor Mamikonian", "Contains some of Armenia's oldest frescoes", "The palace ruins date to the 7th century", "Located on the southern slope of Mt. Aragats"],
      es: ["Aruchavank fue fundada en el siglo VII.", "La iglesia principal está consagrada al siglo X.", "El complejo se extiende sobre 3 hectáreas.", "Aruchavank está bajo protección de monumentos desde 2008."],
      pt: ["Aruchavank foi fundada no século VII.", "A igreja principal é dedicada ao século X.", "O complexo estende-se por 3 hectares.", "Aruchavank está sob proteção de monumentos desde 2008."],
      fr: ["Aruchavank a été fondée au VIIe siècle.", "L'église principale est consacrée au Xe siècle.", "Le complexe s'étend sur 3 hectares.", "Aruchavank est classée monument historique depuis 2008."],
    },
